config.script:
// Formata número em reais (18844.0 -> 18.844,00).
function brl(v){ if(v===undefined||v===null||v==='') return '?';
  var n=Number(v); if(isNaN(n)) return String(v);
  var neg=n<0; n=Math.abs(n); var s=n.toFixed(2); var pp=s.split('.'); var ip=pp[0], dc=pp[1];
  var out='', c=0; for(var i=ip.length-1;i>=0;i--){ out=ip.charAt(i)+out; c++; if(c%3===0&&i>0) out='.'+out; }
  return (neg?'-':'')+out+','+dc; }
// Avisa quem aprova, com paciente, valores, quem pediu e os itens da venda.
var subject = event.subject || {};
var safe = event.payload_safe || {};
var vendaId = subject.venda_id || subject.id;
var clienteId = subject.cliente_id;
var solicitante = subject.user_id;
var numero = safe.numero || vendaId || '?';
var pct = safe.desconto_percentual;
var valorTotal = safe.valor_total;
var alvoRole = config.alvo_role || 'administrador';
var basePath = config.base_path || '/financeiro/aprovacoes-desconto';

// Venda: itens e valor do desconto.
var descontoValor = null;
var itens = [];
if (vendaId) {
  var rv = call('buscar_venda', { venda_id: String(vendaId) });
  if (rv && rv.ok !== false && rv.body) {
    var venda = rv.body.data || rv.body;
    descontoValor = venda.desconto_valor;
    if (venda.valor_total !== undefined && venda.valor_total !== null) { valorTotal = venda.valor_total; }
    itens = venda.itens || [];
  } else { log('notificador: buscar_venda falhou (segue sem itens)'); }
}

// Paciente: sem acesso, o aviso sai sem o nome.
var paciente = null;
if (clienteId) {
  var rc = call('buscar_cliente', { cliente_id: String(clienteId) });
  if (rc && rc.ok !== false && rc.body) {
    var cli = rc.body.data || rc.body;
    paciente = cli.nome;
  } else { log('notificador: buscar_cliente sem acesso (aviso sem nome do paciente)'); }
}

// Quem pediu: sem nome, mostra o próprio id.
var solicitanteNome = null;
if (solicitante) {
  var ru = call('buscar_usuario', { user_id: String(solicitante) });
  if (ru && ru.ok !== false && ru.body) {
    var usr = ru.body.data || ru.body;
    solicitanteNome = usr.nome || usr.username || (usr.profissional && usr.profissional.nome) || null;
  } else { log('notificador: buscar_usuario falhou (solicitante sem nome)'); }
}

var linhas = [];
if (paciente) { linhas.push('**Paciente:** ' + paciente); }
if (valorTotal !== undefined && valorTotal !== null) { linhas.push('**Total:** R$ ' + brl(valorTotal)); }
var descLinha = '**Desconto:** ' + ((pct !== undefined && pct !== null) ? (pct + '%') : '?');
if (descontoValor !== undefined && descontoValor !== null) { descLinha = descLinha + ' (R$ ' + brl(descontoValor) + ')'; }
linhas.push(descLinha);
if (solicitante) { linhas.push('**Solicitado por:** ' + (solicitanteNome || solicitante)); }
if (itens && itens.length > 0) {
  linhas.push('');
  linhas.push('**Itens (' + itens.length + '):**');
  var max = (itens.length > 5) ? 5 : itens.length;
  for (var i = 0; i < max; i++) {
    var it = itens[i];
    var nomeItem = it.procedimento_nome || it.produto_nome || it.pacote_nome || 'Item';
    var q = it.quantidade || 1;
    linhas.push('- ' + q + 'x ' + nomeItem);
  }
  if (itens.length > max) { linhas.push('- _(+ ' + (itens.length - max) + ' item(ns))_'); }
}
var corpo = 'A venda **' + numero + '** tem um desconto aguardando a sua aprovação.\n\n' + linhas.join('\n');

var botoes = [];
if (vendaId) {
  botoes.push({ label: 'Aprovar', estilo: 'primary', acao: { tipo: 'evento', event_type: 'desconto.aprovar', payload: { venda_id: String(vendaId) } } });
  botoes.push({ label: 'Rejeitar', estilo: 'danger', acao: { tipo: 'evento', event_type: 'desconto.rejeitar', payload: { venda_id: String(vendaId) } } });
}
botoes.push({ label: 'Abrir aprovações', estilo: 'secondary', acao: { tipo: 'link', href: basePath } });

var r = call('emitir_ui', { type: 'diretiva_ui', ref: (vendaId ? ('venda:' + String(vendaId)) : undefined), kind: 'modal', titulo: 'Desconto aguardando aprovação', corpo: corpo, botoes: botoes, alvo: { role: alvoRole }, persistencia: 'persistente' });
if (r && r.ok === false) { log('notificador: emitir_ui falhou HTTP ' + r.status_code); return { erro: 'emitir_ui', status: r.status_code }; }
log('notificador: aviso p/ role=' + alvoRole + ' (venda ' + numero + ', paciente=' + (paciente ? 'sim' : 'não') + ', itens=' + itens.length + ')');
return { emitido: true, venda_id: vendaId ? String(vendaId) : null, itens: itens.length };

// Abre a tarefa de aprovação, com a prioridade pela faixa do desconto.
var subject = event.subject || {};
var safe = event.payload_safe || {};
var vendaId = subject.venda_id || subject.id;
if (!vendaId) { log('classificador: sem venda_id'); return { skip: 'sem_venda_id' }; }
vendaId = String(vendaId);
var numero = safe.numero || vendaId;
var pct = Number(safe.desconto_percentual || 0);
var limAlta = Number(config.faixa_alta_pct || 20);
var limMedia = Number(config.faixa_media_pct || 10);
var prioridade = 'baixa';
if (pct >= limAlta) { prioridade = 'alta'; } else if (pct >= limMedia) { prioridade = 'media'; }

var r = call('criar_tarefa', {
  titulo: 'Aprovar desconto de ' + pct + '% na venda ' + numero,
  descricao: 'Desconto acima do teto aguardando aprovação. Abra a fila de aprovações de desconto para decidir.',
  prioridade: prioridade,
  vinculos: [{ tipo: 'venda', ref_id: vendaId }]
});
if (r && r.ok === false) { log('classificador: criar_tarefa falhou HTTP ' + r.status_code); return { erro: 'criar_tarefa', status: r.status_code }; }
log('classificador: tarefa criada (venda ' + numero + ' prioridade ' + prioridade + ')');
return { tarefa: true, venda_id: vendaId, prioridade: prioridade };

// Aprova ou recusa o desconto em nome de quem clicou no aviso.
// Sem saber quem clicou, não decide.
var safe = event.payload_safe || {};
var subject = event.subject || {};
var intent = safe.intent || '';
if (intent !== 'desconto.aprovar' && intent !== 'desconto.rejeitar') { return { skip: 'intent_alheio' }; }
var vendaId = subject.venda_id;
if (!vendaId) { log('executor: sem venda_id'); return { skip: 'sem_venda_id' }; }
vendaId = String(vendaId);
var autorizadoPor = subject.autorizado_por;
if (!autorizadoPor) { log('executor: sem quem clicou (venda ' + vendaId + '), não decide', 'warning'); return { skip: 'sem_autorizado_por', venda_id: vendaId }; }
var acao = (intent === 'desconto.aprovar') ? 'aprovar_desconto' : 'rejeitar_desconto';
var payload = { venda_id: vendaId, em_nome_de: String(autorizadoPor) };
if (intent === 'desconto.rejeitar') { payload.motivo = 'Rejeitado pelo gestor pelo aviso.'; }
var r = call(acao, payload);
if (r && r.ok === false) { log('executor: ' + acao + ' falhou HTTP ' + r.status_code); return { erro: acao, status: r.status_code }; }
log('executor: ' + acao + ' ok (venda ' + vendaId + ', em nome de quem clicou)');
return { executado: acao, venda_id: vendaId };

// Desconto recusado: faz o que a clínica configurou (manter ou cancelar a venda).
var subject = event.subject || {};
var vendaId = subject.venda_id || subject.id;
if (!vendaId) { return { skip: 'sem_venda_id' }; }
vendaId = String(vendaId);
var acaoConfig = config.acao_rejeicao || 'manter';
if (acaoConfig === 'manter') { log('remediador: manter (venda ' + vendaId + '), desconto de volta ao teto'); return { acao: 'manter', venda_id: vendaId }; }
if (acaoConfig === 'cancelar') {
  var r = call('cancelar', { venda_id: vendaId, motivo: 'Desconto recusado (política da clínica: cancelar).' });
  if (r && r.ok === false) { log('remediador: cancelar falhou HTTP ' + r.status_code); return { erro: 'cancelar', status: r.status_code }; }
  log('remediador: venda ' + vendaId + ' cancelada (desconto recusado)');
  return { acao: 'cancelar', venda_id: vendaId };
}
return { acao: acaoConfig, venda_id: vendaId, skip: 'acao_desconhecida' };

// Fecha o ciclo do desconto:
//  - decidido (aprovado ou recusado): fecha o aviso daquela venda para toda a equipe,
//    avisa quem decidiu e conclui a tarefa de aprovação;
//  - venda cancelada com o desconto ainda pendente: fecha o aviso e conclui a tarefa,
//    sem aviso de decisão.
// Cada passo segue mesmo se outro falhar.
var subject = event.subject || {};
var safe = event.payload_safe || {};
var et = event.event_type ? String(event.event_type) : '';
var vendaId = subject.venda_id || subject.id;
if (!vendaId) { return { skip: 'sem_venda_id' }; }
vendaId = String(vendaId);
var cancelada = (et === 'vendas.venda_cancelada');
var aprovado = (et === 'vendas.desconto_aprovado');
var alvoRole = config.alvo_role || 'administrador';
var out = { venda_id: vendaId, dispensado: false, avisado: false, tarefas_concluidas: 0 };

// Venda cancelada: só age se o desconto ainda aguardava aprovação.
if (cancelada) {
  out.cancelada = true;
  var rv = call('buscar_venda', { venda_id: vendaId });
  if (!rv || rv.ok === false || !rv.body) {
    log('fechador: venda ' + vendaId + ' cancelada, mas não deu para ler o desconto (nada feito)');
    return { skip: 'venda_indisponivel', venda_id: vendaId, cancelada: true };
  }
  var venda = rv.body.data || rv.body;
  if (venda.desconto_aprovacao !== 'pendente') {
    return { skip: 'sem_desconto_pendente', venda_id: vendaId, cancelada: true };
  }
}

// Fecha o aviso daquela venda (e só dela) para toda a equipe.
var r = call('dismiss_diretiva', { ref: 'venda:' + vendaId });
if (r && r.ok === false) { log('fechador: dismiss falhou HTTP ' + r.status_code); out.erro_dismiss = r.status_code || 'falha'; }
else { out.dispensado = true; log('fechador: aviso da venda ' + vendaId + ' fechado para todos'); }

// Avisa o mesmo papel quem decidiu.
if (!cancelada) {
  var decisor = aprovado ? (safe.aprovado_por || subject.user_id) : (safe.rejeitado_por || subject.user_id);
  var nome = null;
  if (decisor) {
    var ru = call('buscar_usuario', { user_id: String(decisor) });
    if (ru && ru.ok !== false && ru.body) {
      var usr = ru.body.data || ru.body;
      nome = usr.nome || usr.username || (usr.profissional && usr.profissional.nome) || null;
    } else { log('fechador: buscar_usuario falhou (aviso sem nome)'); }
  }
  if (!nome) { nome = 'alguém da equipe'; }

  var pctTxt = function (v) {
    if (v === undefined || v === null || v === '') { return null; }
    var n = Number(v); if (isNaN(n)) { return null; }
    var s = (Math.round(n * 100) / 100).toString();
    return s.replace('.', ',') + '%';
  };
  var pct = pctTxt(aprovado ? safe.desconto_percentual : safe.desconto_percentual_anterior);
  var numero = safe.numero ? String(safe.numero) : null;
  var texto = 'Desconto';
  if (pct) { texto = texto + ' de ' + pct; }
  if (numero) { texto = texto + ' da venda ' + numero; }
  texto = texto + (aprovado ? ' aprovado por ' : ' recusado por ') + nome;
  var message = { type: 'info', title: aprovado ? 'Desconto aprovado' : 'Desconto recusado', text: texto, icon: aprovado ? 'mdi-check-circle' : 'mdi-close-circle' };
  var rn = call('notificar_grupo', { type: 'mensagem', message: message, group_id: String(alvoRole) });
  if (rn && rn.ok === false) { log('fechador: notificar_grupo falhou HTTP ' + rn.status_code); out.erro_aviso = rn.status_code || 'falha'; }
  else { out.avisado = true; log('fechador: aviso de decisão p/ role=' + alvoRole + ' (venda ' + (numero || vendaId) + ')'); }
}

// Conclui a tarefa de aprovação desta venda aberta pelo time
// ("Aprovar desconto de ...% na venda ..."); só as abertas, nunca outras tarefas da venda.
function eDoTime(t) {
  if (!t || t.estado === 'done' || t.arquivada_em) { return false; }
  var titulo = String(t.titulo || '');
  if (titulo.indexOf('Aprovar desconto de ') !== 0 || titulo.indexOf('% na venda ') < 0) { return false; }
  var vs = t.vinculos || [];
  for (var i = 0; i < vs.length; i++) {
    if (vs[i] && vs[i].tipo === 'venda' && String(vs[i].ref_id) === vendaId) { return true; }
  }
  return false;
}
var rl = call('listar_tarefas_vinculo', { vinculo_tipo: 'venda', vinculo_ref_id: vendaId });
if (rl && rl.ok !== false && rl.body) {
  var corpo = rl.body.data || rl.body;
  var items = corpo.items || [];
  for (var j = 0; j < items.length; j++) {
    var t = items[j];
    if (!eDoTime(t)) { continue; }
    var rm = call('mudar_estado', { id: String(t.id), estado: 'done' });
    if (rm && rm.ok === false) { log('fechador: concluir tarefa falhou HTTP ' + rm.status_code); out.erro_tarefa = rm.status_code || 'falha'; }
    else { out.tarefas_concluidas = out.tarefas_concluidas + 1; }
  }
  log('fechador: ' + out.tarefas_concluidas + ' tarefa(s) de aprovação concluída(s) (venda ' + vendaId + ')');
} else { log('fechador: listar tarefas falhou' + (rl ? (' HTTP ' + rl.status_code) : '')); out.erro_listar = (rl && rl.status_code) ? rl.status_code : 'falha'; }

return out;
